The following snippet shows how you can access the Azure Sql Server from a Azure Function. notice how the connection string indicated that authentication is handled by the managed identity.
So on a connection being made Sql with take a Identity token pased by the function and validate it with identity in AD.
public static class Function1
{
    private static SqlConnection connection = new SqlConnection();

    [FunctionName("Function1")]
    public static async Task&lt;IActionResult&gt; Run(
        [HttpTrigger(AuthorizationLevel.Function, "get", "post", Route = null)] HttpRequest req,
        ILogger log)
    {
        try
        {
            connection.ConnectionString = "Server=sql-mifunctest-vse-ne.database.windows.net; Authentication=Active Directory Managed Identity; Database=MiFuncTest";
            await connection.OpenAsync();
            var cmd = connection.CreateCommand();
            cmd.CommandText = "select * from [dbo].[WebEnquiry]";

            var response = await cmd.ExecuteReaderAsync();

            var result = "";
            while (response.Read())
            { 
                Console.WriteLine(response["Id"].ToString());
                result += response["Id"].ToString() + "\n";
            }
            response.Close();

            return new OkObjectResult($"The database connection is: {connection.State}  Result {result}");
        }
        catch (SqlException sqlex)
        {
            return new OkObjectResult($"The following SqlException happened: {sqlex.Message}");
        }
        catch (Exception ex)
        {
            return new OkObjectResult($"The following Exception happened: {ex.Message}");
        }
    }
}

Integration testing of azure functions is essential when demostrating that a service does what its supposed to do, and also responds in the way you expect. This post shows how you can construct a unit test, in this case Specflow, so that it excutes the function as a background process, so that you can test it using standard http calls.
This process uses the Azure Functions Core Tools cli interface https://go.microsoft.com/fwlink/?linkid=2174087 which should be installed. This should also be installed as part of the build process.
  - task: PowerShell@2
    inputs:
      targetType: 'inline'
      script: 'choco install azure-functions-core-tools -y'
This snippet demostrates how to instatiate the Azure function at the start of the unit test and kill it off after the test has completed. N.B the Directory Info object you pass is the directory of your azure function source code.
namespace ImageResizerTests
{
    [Binding]
    public class ResizerSteps
    {
        private string request;
        private IFlurlResponse response;
        private static TemporaryAzureFunctionsApplication azfunc;

        [BeforeTestRun(Order = 1)]
        public static void Before()
        {
            var dirInfo = new DirectoryInfo("..\\..\\..\\..\\..\\src\\Application\\KnightFrank.Hub.Watermark");
            Console.WriteLine($"Directory : {dirInfo.ToString()}");

            azfunc = TemporaryAzureFunctionsApplication.StartNewAsync(dirInfo).Result;
        }

        [AfterTestRun]
        public static void After()
        {
            azfunc.DisposeAsync();
        }

        [When(@"the URI is evaluated")]
        public void WhenTheURIIsEvaluated()
        {
            try
            {
                response = "http://localhost:7071/api/Resize"
                    .WithHeader("Accept", "*/*")
                    .WithHeader("Content_Type", "application/json")
                    .AllowAnyHttpStatus()
                    .PostJsonAsync(new { Size = "SmallThumbnail", InputUri = request }).Result;
            }
            catch(Exception ex)
            {
                Console.WriteLine(ex.Message);
            }
        }
    }
}
