How ? In your Azure Functions Project Create a files called proxies.json and insert the following code
proxies.json
{
  "$schema": "http://json.schemastore.org/proxies",
    "proxies": {
      "api": {
        "matchCondition": {
          "route": "/api/{*url}"
        },
        "backendUri": "Set With Build Variable/{url}"
      },
      "app": {
        "matchCondition": {
          "route": "{*url}",
          "methods": [ "GET", "HEAD", "OPTIONS" ]
        },
        "backendUri": "Set With Build Variable/{url}"
      },
      "appResources": {
        "matchCondition": {
          "route": "/static/{*url}",
          "methods": [ "GET", "HEAD", "OPTIONS" ]
        },
        "backendUri": "Set With Build Variable/{url}"
      }
    }
  }
